"""pmrf/simulate/result.py"""

from jaxtyping import ArrayLike
import jax.numpy as jnp
import equinox as eqx

from pmrf.simulate.base import AdmittanceResult, ScatteringResult, TransferResult
from pmrf.rf import y2s, s2y, s2z, y2z, a2s, a2y, a2z, s2a, y2a


class SimulateResult(eqx.Module):
    """
    A unified container for simulation results.

    Provides conversions between parameter domains (s, y, z, a)
    regardless of the underlying solver's domain.
    """
    #: The underlying domain-specific result generated by the solver.
    solution: AdmittanceResult | ScatteringResult | TransferResult
    
    #: The reference characteristic impedance to use when converting to or 
    #: from scattering parameters (S-parameters). Default is 50.0.
    z0: ArrayLike = 50.0
    
    @property
    def s(self) -> jnp.ndarray:
        """Scattering parameters (S-parameters) of the network."""
        if isinstance(self.solution, ScatteringResult):
            return self.solution.s
        elif isinstance(self.solution, AdmittanceResult):
            return y2s(self.solution.y, z0=self.z0)
        elif isinstance(self.solution, TransferResult):
            return a2s(self.solution.a, z0=self.z0)
        else:
            raise ValueError(f"Unknown underlying solution type: {type(self.solution)}")
            
    @property
    def y(self) -> jnp.ndarray:
        """Admittance parameters (Y-parameters) of the network."""
        if isinstance(self.solution, ScatteringResult):
            return s2y(self.solution.s, z0=self.z0)
        elif isinstance(self.solution, AdmittanceResult):
            return self.solution.y
        elif isinstance(self.solution, TransferResult):
            return a2y(self.solution.a)
        else:
            raise ValueError(f"Unknown underlying solution type: {type(self.solution)}")

    @property
    def z(self) -> jnp.ndarray:
        """Impedance parameters (Z-parameters) of the network."""
        if isinstance(self.solution, ScatteringResult):
            return s2z(self.solution.s, z0=self.z0)
        elif isinstance(self.solution, AdmittanceResult):
            return y2z(self.solution.y)
        elif isinstance(self.solution, TransferResult):
            return a2z(self.solution.a)
        else:
            raise ValueError(f"Unknown underlying solution type: {type(self.solution)}")

    @property
    def a(self) -> jnp.ndarray:
        """Transfer parameters (ABCD-parameters) of the network."""
        if isinstance(self.solution, ScatteringResult):
            return s2a(self.solution.s, z0=self.z0)
        elif isinstance(self.solution, AdmittanceResult):
            return y2a(self.solution.y)
        elif isinstance(self.solution, TransferResult):
            return self.solution.a
        else:
            raise ValueError(f"Unknown underlying solution type: {type(self.solution)}")